/** Routes tagged `catalog · fichas técnicas`. */
export class CatalogFichasTecnicasResource extends Resource {
  /**
   * Aposenta a ficha.
   *
   * Terminal, e não há remoção: ordens de transformação passadas citam a ficha
   * que usaram, e apagá-la deixaria essa citação órfã.
   *
   * `POST /v1/catalog/boms/{id}/archive`
   *
   * @param id ID da ficha
   * @param options Per-call overrides.
   */
  archiveBom(id: string, options?: RequestOptions): Promise<S.CatalogBomDto> {
    return this._http.request({ method: 'POST', path: `/v1/catalog/boms/${seg(id)}/archive`, options });
  }

  /**
   * Cadastra a ficha técnica.
   *
   * A ficha diz **proporção**: o que é consumido, o que resulta e como o custo
   * do que entrou se distribui entre o que sai. Ela não custeia nada; quem
   * transforma proporção em custo é o motor do estoque, na ordem de
   * transformação.
   *
   * A ficha é **opcional** para transformar: ela poupa digitação, e o
   * desmembramento (em que cada peça rende diferente) roda sem nenhuma.
   *
   * `POST /v1/catalog/boms`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createBom(body: S.CreateBomBody, options?: RequestOptions): Promise<S.CatalogBomDto> {
    return this._http.request({ method: 'POST', path: `/v1/catalog/boms`, body, options });
  }

  /**
   * A ficha, com as linhas.
   *
   * A ficha é o cadastro da composição: o que entra, o que sai e a cota de cada
   * resultante. Quem a executa é o `stock`, e ele a lê **uma vez**, ao montar
   * a ordem de transformação.
   *
   * `GET /v1/catalog/boms/{id}`
   *
   * @param id ID da ficha
   * @param options Per-call overrides.
   */
  getBom(id: string, options?: RequestOptions): Promise<S.CatalogBomDto> {
    return this._http.request({ method: 'GET', path: `/v1/catalog/boms/${seg(id)}`, options });
  }

  /**
   * Lista as fichas do tenant.
   *
   * O filtro por `variant_id` é o que responde *"onde este insumo é usado?"*
   * antes de alguém aposentar um SKU.
   *
   * `GET /v1/catalog/boms`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listBoms(query?: CatalogFichasTecnicasListBomsQuery, options?: RequestOptions): Promise<S.CatalogBomPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/catalog/boms`, query, options });
  }

  /**
   * Iterates every item of `listBoms`, following `next_page_token` page after page.
   *
   * `GET /v1/catalog/boms`
   */
  listBomsAll(query?: CatalogFichasTecnicasListBomsQuery, options?: RequestOptions): Paginator<NonNullable<S.CatalogBomPageDto["items"]>[number], S.CatalogBomPageDto> {
    return new Paginator((page_token) => this.listBoms({ ...query, page_token } as CatalogFichasTecnicasListBomsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Substitui cabeçalho e linhas.
   *
   * ⚠️ `PUT` e não `PATCH` porque as linhas são **substituídas**, nunca
   * mescladas: uma ficha é uma composição, e mesclar deixaria um insumo removido
   * continuar valendo porque ninguém o citou na atualização.
   *
   * O `code` fica de fora: é a chave que integração de terceiro guarda.
   *
   * `PUT /v1/catalog/boms/{id}`
   *
   * @param id ID da ficha
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateBom(id: string, body: S.UpdateBomBody, options?: RequestOptions): Promise<S.CatalogBomDto> {
    return this._http.request({ method: 'PUT', path: `/v1/catalog/boms/${seg(id)}`, body, options });
  }
}

